begin;
create extension if not exists pgtap with schema extensions;
select extensions.plan(15);
insert into auth.users (id) values ('00000000-0000-0000-0000-000000000001'), ('00000000-0000-0000-0000-000000000002');
set local role authenticated;
select set_config('request.jwt.claim.sub', '00000000-0000-0000-0000-000000000001', true);
select extensions.lives_ok($$select public.submit_leaderboard_snapshot('A','ABCDEF',10,10,5,2,600,5,10,8)$$, 'A submits own scores');
select extensions.throws_ok($$select public.submit_leaderboard_snapshot('A','ABCDEF',9,10,5,2,600,5,10,8)$$, '22023', 'cumulative values cannot decrease', 'total sessions cannot regress');
select extensions.throws_ok($$select public.submit_leaderboard_snapshot('A','ABCDEF',10,9,5,2,600,5,10,8)$$, '22023', 'cumulative values cannot decrease', 'unique verses cannot regress');
select extensions.throws_ok($$select public.submit_leaderboard_snapshot('A','ABCDEF',10,10,4,2,600,5,10,8)$$, '22023', 'cumulative values cannot decrease', 'max streak cannot regress');
select extensions.throws_ok($$select public.submit_leaderboard_snapshot('A','ABCDEF',10,10,5,1,600,5,10,8)$$, '22023', 'cumulative values cannot decrease', 'badge awards cannot regress');
select extensions.throws_ok($$select public.submit_leaderboard_snapshot('A','ABCDEF',10,10,5,2,599,5,10,8)$$, '22023', 'cumulative values cannot decrease', 'duration cannot regress');
select extensions.lives_ok($$select public.submit_leaderboard_snapshot('A','ABCDEF',10,10,5,2,600,0,11,8)$$, 'current streak and accuracy can decrease');
select extensions.throws_ok($$select public.get_leaderboard('registration_time',50)$$, '22023', 'unsupported metric', 'metric allowlist');
select extensions.throws_ok($$select public.submit_leaderboard_snapshot('A','ABCDEF',-1,10,5,2,600,0,11,8)$$, '22023', 'invalid snapshot', 'negative scores rejected');
select extensions.throws_ok($$select public.submit_leaderboard_snapshot('A','ABCDEF',10,10,5,2,600,0,2,3)$$, '22023', 'invalid snapshot', 'correct must not exceed answered');
select set_config('request.jwt.claim.sub', '00000000-0000-0000-0000-000000000002', true);
select extensions.lives_ok($$select public.submit_leaderboard_snapshot('B','GHIJKL',20,20,5,2,600,0,0,0)$$, 'B submits own scores');
select extensions.is((select count(*)::integer from public.leaderboard_score),1,'RLS only exposes own row');
select extensions.is((public.get_leaderboard('total_sessions',1)->'current_user'->>'rank')::integer,1,'current caller rank included');
select extensions.is(jsonb_array_length(public.get_leaderboard('quiz_accuracy',50)->'entries'),1,'zero answered excluded');
select extensions.throws_ok($$update public.leaderboard_score set total_sessions=999 where user_id='00000000-0000-0000-0000-000000000001'$$,'42501', 'permission denied for table leaderboard_score','raw updates forbidden; writes only through guarded RPC');
reset role;
select * from extensions.finish();
rollback;
